class StoreError(Exception):
    """Base exception for store-level failures."""


class CorruptDbError(StoreError):
    """Raised when the db file is unparseable or contains invalid data."""


class NotFoundError(StoreError):
    """Raised when a requested expense id does not exist."""


def _deserialize_expense(obj: dict) -> Expense:
    """Convert a dict from JSON into an Expense, raising CorruptDbError on bad data."""
    try:
        return Expense(
            id=int(obj["id"]),
            amount=Decimal(obj["amount"]),
            category=str(obj["category"]),
            note=str(obj.get("note", "")),
        )
    except (KeyError, TypeError, InvalidOperation, ValueError) as exc:
        raise CorruptDbError(f"Invalid expense record: {obj}") from exc


def _serialize_expense(exp: Expense) -> dict:
    """Convert an Expense to a plain dict for JSON serialization."""
    return {
        "id": exp.id,
        "amount": str(exp.amount),
        "category": exp.category,
        "note": exp.note,
    }


def _next_id(expenses: list[Expense]) -> int:
    """Return the next available id (max existing id + 1, or 1 if empty)."""
    return max((e.id for e in expenses), default=0) + 1


def load_store(db_path: str) -> list[Expense]:
    """Load expenses from a JSON file, raising CorruptDbError if invalid."""
    if not os.path.exists(db_path):
        return []
    try:
        with open(db_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as exc:
        raise CorruptDbError(f"Cannot read store: {db_path}") from exc
    if not isinstance(data, list):
        raise CorruptDbError("Store root must be a JSON array")
    try:
        return [_deserialize_expense(obj) for obj in data]
    except CorruptDbError:
        raise
    except Exception as exc:
        raise CorruptDbError(f"Invalid store data: {exc}") from exc


def save_store(db_path: str, expenses: list[Expense]) -> None:
    """Write the expense list to a JSON file."""
    with open(db_path, "w", encoding="utf-8") as f:
        json.dump([_serialize_expense(e) for e in expenses], f, indent=2)


def add_expense(db_path: str, amount: Decimal, category: str, note: str = "") -> Expense:
    """Append an expense and return it with its auto-incremented id."""
    expenses = load_store(db_path)
    new_id = _next_id(expenses)
    exp = Expense(id=new_id, amount=amount, category=category, note=note)
    expenses.append(exp)
    save_store(db_path, expenses)
    return exp


def list_expenses(db_path: str) -> list[Expense]:
    """Return all expenses sorted by id ascending."""
    expenses = load_store(db_path)
    return sorted(expenses, key=lambda e: e.id)


def total_expenses(db_path: str, category: str | None = None) -> Decimal:
    """Return the sum of amounts, optionally filtered by category."""
    expenses = load_store(db_path)
    if category is not None:
        expenses = [e for e in expenses if e.category == category]
    return sum((e.amount for e in expenses), Decimal("0"))


def delete_expense(db_path: str, expense_id: int) -> Expense:
    """Remove and return the expense with the given id, raising NotFoundError if missing."""
    expenses = load_store(db_path)
    for i, exp in enumerate(expenses):
        if exp.id == expense_id:
            removed = expenses.pop(i)
            save_store(db_path, expenses)
            return removed
    raise NotFoundError(f"Expense {expense_id} not found")
